<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Throwable; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Pterodactyl\Services\Dezerx\ServerVariables; class LaunchConfigurator { public const ARGFILE = 'unix_args.txt'; private const ARGFILE_ROOTS = [ 'libraries/net/neoforged/neoforge', 'libraries/net/minecraftforge/forge', ]; private const MAX_ARGFILE = 262_144; private const NOT_LAUNCHABLE = ['minecraft_server', 'installer', 'bootstrap', 'original']; public function apply(Server $server, ServerFiles $files, int $java = 0, string $preferredJar = 'server.jar'): array { $argfile = $this->argfile($files); $startup = (string) $server->startup; $target = null; $mode = 'unchanged'; if ($argfile !== null) { $mode = $this->publishArgfile($files, $argfile, $preferredJar) ? 'argfile' : 'unchanged'; if ($mode === 'argfile') { $startup = $this->argfileStartup($startup); $target = '@' . self::ARGFILE; } } else { $files->deletePaths('/', [self::ARGFILE]); $jar = $this->jar($files, $preferredJar); if ($jar !== null) { $mode = 'jar'; $target = $jar; $startup = $this->jarStartup($server, $startup, $jar); } } $image = $this->image($server, $java); $changed = $this->save($server, $startup, $image); return [ 'target' => $target, 'mode' => $mode, 'image' => $changed['image'], 'startup' => $changed['startup'], ]; } public function argfile(ServerFiles $files): ?string { foreach (self::ARGFILE_ROOTS as $root) { $entries = $files->listFiles('/' . $root) ?? []; usort( $entries, fn (array $a, array $b) => strcmp((string) ($b['modified_at'] ?? ''), (string) ($a['modified_at'] ?? '')), ); foreach ($entries as $entry) { if (!($entry['directory'] ?? false)) { continue; } $directory = $root . '/' . (string) $entry['name']; if ($files->entrySize('/' . $directory, self::ARGFILE) !== null) { return $directory . '/' . self::ARGFILE; } } } return null; } private function publishArgfile(ServerFiles $files, string $argfile, string $preferredJar = 'server.jar'): bool { $contents = $files->fileContents('/' . $argfile, self::MAX_ARGFILE); if ($contents === null || trim($contents) === '') { return false; } $contents = $this->repointJar($files, $argfile, $contents, $preferredJar); $files->deletePaths('/', [self::ARGFILE]); return $files->writeFile('/' . self::ARGFILE, $contents); } private function repointJar(ServerFiles $files, string $argfile, string $contents, string $preferredJar): string { if (preg_match('/-jar\s+(?:"([^"]+)"|\'([^\']+)\'|(\S+))/', $contents, $match) !== 1) { return $contents; } $named = $match[1] !== '' ? $match[1] : ($match[2] !== '' ? $match[2] : ($match[3] ?? '')); if ($named === '' || str_contains($named, '/')) { return $contents; } if ($files->entrySize('/', $named) !== null) { return $contents; } $replacement = null; foreach ([$preferredJar, 'server.jar'] as $candidate) { if ($candidate !== '' && $files->entrySize('/', $candidate) !== null) { $replacement = $candidate; break; } } if ($replacement === null) { $directory = dirname($argfile); if ($directory !== '.' && $files->entrySize('/' . $directory, $named) !== null) { $replacement = $directory . '/' . $named; } } if ($replacement === null) { return $contents; } Log::info('Repointing an argfile jar that is not at the server root', ['server' => $files->server->uuid, 'named' => $named, 'used' => $replacement]); return str_replace($match[0], '-jar ' . $replacement, $contents); } private function argfileStartup(string $startup): string { if (str_contains($startup, self::ARGFILE)) { return $startup; } $rewritten = preg_replace( '/-jar\s+(?:"[^"]*"|\'[^\']*\'|\S+)/', '@' . self::ARGFILE, $startup, 1, ); return is_string($rewritten) ? $rewritten : $startup; } private function jarStartup(Server $server, string $startup, string $jar): string { $token = $this->hasJarVariable($server) ? '{{SERVER_JARFILE}}' : $jar; if ($token === '{{SERVER_JARFILE}}') { ServerVariables::set($server, 'SERVER_JARFILE', $jar); } if (str_contains($startup, self::ARGFILE)) { if (str_contains($startup, '-f ' . self::ARGFILE)) { return $token === '{{SERVER_JARFILE}}' ? $startup : str_replace('{{SERVER_JARFILE}}', $token, $startup); } return str_replace('@' . self::ARGFILE, '-jar ' . $token, $startup); } $rewritten = preg_replace( '/-jar\s+(?:"[^"]*"|\'[^\']*\'|\S+)/', '-jar ' . $token, $startup, 1, ); return is_string($rewritten) ? $rewritten : $startup; } private function jar(ServerFiles $files, string $preferred): ?string { $jars = []; foreach ($files->listFiles('/') ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if (($entry['directory'] ?? false) || !str_ends_with(mb_strtolower($name), '.jar')) { continue; } $jars[$name] = ['size' => (int) ($entry['size'] ?? 0), 'modified' => (string) ($entry['modified_at'] ?? '')]; } if ($jars === []) { return null; } $launchable = array_filter( $jars, fn (array $meta, string $name) => !$this->isDependency($name), ARRAY_FILTER_USE_BOTH, ); $newest = null; foreach ($launchable as $name => $meta) { if ($newest === null || strcmp($meta['modified'], $launchable[$newest]['modified']) > 0) { $newest = $name; } } foreach ([$preferred, 'server.jar'] as $candidate) { if ($candidate === '' || !array_key_exists($candidate, $jars)) { continue; } if ( $newest !== null && $newest !== $candidate && strcmp($launchable[$newest]['modified'], $jars[$candidate]['modified']) > 0 ) { return $newest; } return $candidate; } if ($launchable === []) { return null; } uasort($launchable, fn (array $a, array $b) => $b['size'] <=> $a['size']); return (string) array_key_first($launchable); } private function isDependency(string $name): bool { $lower = mb_strtolower($name); foreach (self::NOT_LAUNCHABLE as $marker) { if (str_contains($lower, $marker)) { return true; } } return false; } public function image(Server $server, int $java): ?string { $images = (array) $server->egg->docker_images; if ($java <= 0 || $images === []) { return null; } if (!in_array($server->image, array_values($images), true)) { return null; } $rated = []; foreach ($images as $label => $image) { $version = $this->javaVersion((string) $label . ' ' . (string) $image); if ($version > 0) { $rated[$version] = (string) $image; } } if ($rated === []) { return null; } ksort($rated); foreach ($rated as $version => $image) { if ($version >= $java) { return $image; } } return (string) end($rated); } private function javaVersion(string $haystack): int { return preg_match('/java[\s_-]*(\d{1,2})/i', $haystack, $found) === 1 ? (int) $found[1] : 0; } private function hasJarVariable(Server $server): bool { return ServerVariables::definition($server, 'SERVER_JARFILE') !== null; } private function save(Server $server, string $startup, ?string $image): array { $fill = []; if ($startup !== '' && $startup !== (string) $server->startup) { $fill['startup'] = $startup; } if ($image !== null && $image !== $server->image) { $fill['image'] = $image; } if ($fill === []) { return ['startup' => false, 'image' => null]; } try { $server->forceFill($fill)->saveOrFail(); } catch (Throwable $exception) { Log::warning('Could not write a server startup command', [ 'server' => $server->uuid, 'error' => $exception->getMessage(), ]); return ['startup' => false, 'image' => null]; } return [ 'startup' => array_key_exists('startup', $fill), 'image' => $fill['image'] ?? null, ]; } } 